unsigned checks=0,failures=0;
void Check(bool ok,const std::string& name){++checks;failures+=!ok;std::cout<<(ok?"PASS ":"FAIL ")<<name<<std::endl;}
void Quit(){SDL_Event event{};event.type=SDL_QUIT;SDL_PushEvent(&event);}
int main(int argc,char** argv){if(argc<4)return 2;std::string project=argv[1],mode=argv[2];std::filesystem::path out=argv[3];std::filesystem::create_directories(out);
 unsigned frame=0,phase=0,at=0;uint64_t lastTerrainOwner=0,lastTerrainRevision=0;unsigned returnedAt=0;auto editRequestedAt=std::chrono::steady_clock::now();uint64_t request=0;size_t bodiesBeforeBuild=0;float physicalDistance=0;std::string expected;bool read=mode=="read",performance=mode=="performance",rotatedCase=mode=="rotated",done=false;RuntimeWorld* initial=nullptr;
 std::vector<double> framesMs,physicsMs;double frameMs=0;std::ofstream timings(out/(mode+"-timings.csv"));timings<<"frame,phase,frame_ms,physics_ms,bodies,active_regions,retained_bytes,stream_ms,stream_largest_unit_ms,terrain_prepare_ms,terrain_publish_ms\n";
 ApplicationControl control;control.hidden=true;control.frameSeconds=[&](float actual){frameMs=actual*1000;return 1.f/60;};control.hostReady=[](EngineHost& h){h.GetWindow().SetTestInputMode(true);SDL_GL_SetSwapInterval(0);std::string error;h.Audio().Init(error,true);};
 control.beforeFrame=[&](EngineHost& h,RuntimeWorld&,InteractivePlay&){auto& in=h.GetWindow();if(!read&&phase==1&&frame==at)editRequestedAt=std::chrono::steady_clock::now();in.QueueTestPhysical("mouse:Left",!read&&((!rotatedCase&&phase==1)||(rotatedCase&&phase==31))&&frame==at);in.QueueTestPhysical("key:F2",rotatedCase&&phase==30&&frame==at);in.QueueTestPhysical("key:B",!read&&phase==2&&frame==at);in.QueueTestPhysical("key:F3",!read&&phase==3&&frame==at);in.QueueTestPhysical("key:F1",!read&&phase==4&&frame==at);};
 control.afterFrame=[&](EngineHost& host,RuntimeWorld& w,InteractivePlay&){++frame;std::string error;auto session=w.SceneControl();auto* stream=session?session->Streaming(w,error):nullptr;if(!stream)return;auto owner=stream->Resolve("quarry0",1);auto* terrain=owner?w.LiveTerrain().Status(owner):nullptr;
  auto physical=w.Physics().LastStepStats();auto statistics=stream->Stats();timings<<frame<<','<<phase<<','<<frameMs<<','<<physical.totalMilliseconds<<','<<physical.bodies<<','<<statistics.active<<','<<statistics.retainedBytes<<','<<statistics.integrationMs<<','<<statistics.largestUnitMs<<','<<(terrain?terrain->prepareMs:0)<<','<<(terrain?terrain->publishMs:0)<<'\n';
  if(terrain&&terrain->ready&&(lastTerrainOwner!=owner||lastTerrainRevision!=terrain->revision)){lastTerrainOwner=owner;lastTerrainRevision=terrain->revision;std::cout<<"TERRAIN_COMMIT owner="<<owner<<" revision="<<terrain->revision<<" prepare_ms="<<terrain->prepareMs<<" publish_ms="<<terrain->publishMs<<" estimated_bytes="<<terrain->bytes<<std::endl;}
  if(performance){if(terrain&&terrain->ready&&!terrain->busy){framesMs.push_back(frameMs);physicsMs.push_back(physical.totalMilliseconds);}if(framesMs.size()>=600){for(auto* values:{&framesMs,&physicsMs}){std::sort(values->begin(),values->end());std::cout<<"PERF "<<(values==&framesMs?"frame":"physics")<<" median_ms="<<(*values)[values->size()/2]<<" p95_ms="<<(*values)[values->size()*95/100]<<" worst_ms="<<values->back()<<std::endl;}phase=20;}else return;}
  if(rotatedCase&&phase>=30){auto rotatedOwner=stream->Resolve("quarry2",1);auto* state=rotatedOwner?w.LiveTerrain().Status(rotatedOwner):nullptr;auto* motor=w.RuntimeCharacter(10);
   if(phase==30&&state&&state->ready&&!state->busy&&w.RuntimeDefinition(10)->transform.position.x>90&&motor&&motor->result.supported){std::cout<<"ROTATED_GRAVITY "<<motor->result.gravity.x<<","<<motor->result.gravity.y<<","<<motor->result.gravity.z<<" UP "<<motor->result.up.x<<","<<motor->result.up.y<<","<<motor->result.up.z<<std::endl;Check(motor->result.gravity.x>9&&std::abs(motor->result.gravity.y)<.01f&&motor->result.up.x<-.9f,"actual rotated quarry motor follows the ordinary local gravity region");phase=31;at=frame;}
   else if(phase==31&&state&&state->revision>=2&&!state->busy){auto t=w.RuntimeDefinition(rotatedOwner)->transform;auto hit=w.Physics().Raycast(t.position+t.rotation*glm::vec3(0,-3.4f,8),t.rotation*glm::vec3(0,0,-1),16);Check(hit.hit&&hit.body.id==w.RuntimeBody(rotatedOwner).id,"logical digging publishes real collision in the rotated quarry");Check(state->error.empty()&&motor&&motor->result.supported,"rotated support remains stable after terrain publication");phase=20;}
  }
  if(phase==0&&terrain&&terrain->ready&&!terrain->busy){Check(true,"project JS initializes editable terrain in real application");initial=&w;{std::vector<unsigned char> pixels;host.GetRenderer().CaptureFrame(host.GetWindow().Width(),host.GetWindow().Height(),pixels);WriteRgbPng((out/"initial.png").string(),host.GetWindow().Width(),host.GetWindow().Height(),pixels);}if(rotatedCase){phase=30;at=frame;}else if(read){request=session->Saves(*w.Resources())->Request("load","living-review","","{}",error);Check(request!=0,"queue fresh-process slot load: "+error);phase=10;}else{Check(w.CaptureRuntimeTerrain(owner,expected,error),"initial field capture");phase=1;at=frame;}}
  else if(!read&&phase==1&&terrain&&terrain->revision>=2&&!terrain->busy){std::string changed;w.CaptureRuntimeTerrain(owner,changed,error);Check(changed!=expected,"logical click executes JS brush and publishes changed field");std::cout<<"EDIT_LATENCY_MS "<<std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-editRequestedAt).count()<<std::endl;expected=changed;bodiesBeforeBuild=w.Physics().AliveBodyCount();phase=2;at=frame;}
  else if(!read&&phase==2&&frame>at+8){Check(w.Physics().AliveBodyCount()==bodiesBeforeBuild+1,"JS prefab construction creates actual physical body");phase=3;at=frame;}
  else if(!read&&phase==3){auto rows=stream->Regions();bool unloaded=false;for(auto& r:rows)if(r.id=="quarry0")unloaded=r.state=="unloaded";if(unloaded){Check(!w.RuntimeDefinition(owner),"leaving actually unloads edited source region");phase=4;at=frame;}}
  else if(!read&&phase==4&&terrain&&terrain->ready&&!terrain->busy){auto crate=stream->Resolve("quarry0",20);auto body=w.RuntimeBody(crate);auto floor=w.RuntimeBody(70);if(!returnedAt){returnedAt=frame;std::cout<<"RETURN_PHYSICS crate="<<crate<<" enabled="<<w.Physics().IsBodyEnabled(body)<<" authored="<<w.RuntimeDefinition(crate)->body->enabled<<" floor="<<w.Physics().IsBodyEnabled(floor)<<std::endl;Check(w.Physics().IsBodyEnabled(body),"returned ordinary rigid body remains collision-enabled");}if(frame<returnedAt+120)return;auto position=w.Physics().GetTransform(body).position;std::cout<<"RETURN_POSITION "<<position.x<<","<<position.y<<","<<position.z<<std::endl;Check(position.y>.4f&&position.y<1.0f,"returned crate remains supported during two seconds of actual physics");std::string returned;w.CaptureRuntimeTerrain(owner,returned,error);Check(returned==expected,"return preserves exact edited terrain field");{auto t=w.RuntimeDefinition(owner)->transform;auto hit=w.Physics().Raycast(t.position+t.rotation*glm::vec3(0,-3.4f,8),t.rotation*glm::vec3(0,0,-1),16);Check(hit.hit&&hit.body.id==w.RuntimeBody(owner).id,"committed edited collider answers local cave ray");physicalDistance=hit.distance;}request=session->Saves(*w.Resources())->Request("save","living-review","","{}",error);Check(request!=0,"queue real cold save: "+error);phase=5;}
  else if(phase==5){auto* status=session->Saves(*w.Resources())->Status(request);if(status&&(status->state=="completed"||status->state=="failed")){Check(status->state=="completed","save completes: "+status->error);std::ofstream(out/"expected-terrain.bin",std::ios::binary)<<expected;std::ofstream(out/"expected-ray.txt")<<std::setprecision(9)<<physicalDistance;phase=20;}}
  else if(phase==10){auto* status=session->Saves(*w.Resources())->Status(request);if(status&&(status->state=="completed"||status->state=="failed")){Check(status->state=="completed","fresh-process cold load completes: "+status->error);Check(initial!=&w,"cold load publishes a replacement world");owner=stream->Resolve("quarry0",1);std::string actual;std::ifstream file(out/"expected-terrain.bin",std::ios::binary);expected={std::istreambuf_iterator<char>(file),{}};Check(owner&&w.CaptureRuntimeTerrain(owner,actual,error)&&!expected.empty()&&actual==expected,"restored physical field matches edited pre-exit bytes");if(owner){std::ifstream(out/"expected-ray.txt")>>physicalDistance;auto t=w.RuntimeDefinition(owner)->transform;auto hit=w.Physics().Raycast(t.position+t.rotation*glm::vec3(0,-3.4f,8),t.rotation*glm::vec3(0,0,-1),16);Check(hit.hit&&hit.body.id==w.RuntimeBody(owner).id&&std::abs(hit.distance-physicalDistance)<1e-4f,"fresh-process actual collision endpoint matches saved edited world");}phase=20;}}
  if(phase==20&&!done){done=true;Check(!w.Scripts()||w.Scripts()->Diagnostics().empty(),"project JS has no runtime diagnostics");Quit();}
  if(frame>5000&&!done){Check(false,"bounded application workflow timeout phase "+std::to_string(phase));for(auto& r:stream->Regions()){std::cout<<r.id<<' '<<r.state<<' '<<r.error;for(auto& pin:r.pins)std::cout<<" PIN "<<pin;std::cout<<std::endl;}if(auto* element=w.UI().Element(w.UI().Find("terrain_lab"),"status"))std::cout<<"HUD "<<element->text<<std::endl;if(w.Scripts())for(auto& d:w.Scripts()->Diagnostics())std::cout<<"SCRIPT "<<d.message<<std::endl;done=true;Quit();}
  if(!performance)std::this_thread::sleep_for(std::chrono::milliseconds(1));
 };
 Application app;char name[]="judas";char* args[]={name,const_cast<char*>(project.c_str())};Check(app.Run(2,args,&control)==0,"application shutdown");std::string profileError;PerformanceProfiler::Get().Export((out/(mode+"-profile.json")).string(),profileError);std::cout<<"SUMMARY "<<checks<<" checks "<<failures<<" failures\n";return failures?1:0;
}
